21		CampaignFailed    = "failed"
22	
23		DevicePending     = "pending"     // 尚未领取下载
24		DeviceDownloading = "downloading" // 已领取下载，未完成
25		DeviceReady       = "ready"       // 下载成功，安装尚未领取
