222	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
223	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
224	func (s *Store) CreateCampaign(spec CampaignSpec) error {
225		s.mu.Lock()
226		defer s.mu.Unlock()
227		if err := s.checkOpen(); err != nil {
228			return err
229		}
230		// 先做全部校验，全部通过后才写入，保证原子创建。
231		if spec.ID == "" {
232			return ErrInvalidCampaignID
233		}
234		if spec.Operator == "" {
235			return ErrInvalidOperator
236		}
237		if spec.CreatedAt.IsZero() {
238			return fmt.Errorf("%w: created at", ErrInvalidTime)
239		}
240		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
241			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
242		}
243		if spec.Deadline.IsZero() {
244			return fmt.Errorf("%w: deadline", ErrInvalidTime)
245		}
246		if len(spec.Devices) == 0 {
247			return ErrInvalidDeviceList
248		}
249		seen := make(map[string]bool, len(spec.Devices))
250		for _, id := range spec.Devices {
251			if id == "" {
252				return ErrInvalidDeviceID
253			}
254			if seen[id] {
255				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
256			}
257			seen[id] = true
258		}
259		if spec.BatchSize <= 0 {
260			return ErrInvalidBatchSize
261		}
262		if !spec.WindowStart.Before(spec.WindowEnd) {
263			return ErrInvalidWindow
264		}
265		if !spec.Deadline.After(spec.CreatedAt) {
266			return ErrInvalidDeadline
267		}
268		if spec.TargetVersion == "" {
269			return ErrInvalidVersion
270		}
271		if _, ok := s.versions[spec.TargetVersion]; !ok {
272			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
273		}
274		if _, ok := s.campaigns[spec.ID]; ok {
275			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
276		}
277		ver := s.versions[spec.TargetVersion]
278		devs := make([]*campaignDevice, 0, len(spec.Devices))
279		for i, id := range spec.Devices {
280			d, ok := s.devices[id]
281			if !ok {
282				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
283			}
284			if !containsString(ver.AllowedFrom, d.Version) {
285				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
286			}
287			if s.deviceBusy(id, spec.ID) {
288				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
289			}
290			devs = append(devs, &campaignDevice{
291				DeviceID: id,
292				Batch:    i / spec.BatchSize,
293				Status:   DevicePending,
294				Phase:    StageDownload,
295				Download: opState{ID: operationID(spec.ID, id, StageDownload)},
296				Install:  opState{ID: operationID(spec.ID, id, StageInstall)},
297				Rollback: opState{ID: operationID(spec.ID, id, StageRollback)},
298			})
299		}
300		campaign := &campaignState{
301			ID:                spec.ID,
302			Operator:          spec.Operator,
303			Target:            spec.TargetVersion,
304			CreatedAt:         spec.CreatedAt,
305			BatchSize:         spec.BatchSize,
306			WindowStart:       spec.WindowStart,
307			WindowEnd:         spec.WindowEnd,
308			Deadline:          spec.Deadline,
309			RollbackOnFailure: spec.RollbackOnFailure,
310			Devices:           devs,
311			index:             make(map[string]int, len(devs)),
312			LastTime:          spec.CreatedAt,
313			Status:            CampaignRunning,
314		}
315		for i, cd := range devs {
316			campaign.index[cd.DeviceID] = i
317		}
318		return s.commit(func() error {
319			s.campaigns[spec.ID] = campaign
320			return nil
321		})
322	}
