t.Run("dropping the shared device cannot paper over the conflict", func(t *testing.T) {
	// 模拟“删掉重叠设备再打开”的修复尝试：从 cmp-b 设备列表删掉 d1，
	// 但其下载结果历史仍引用 d1，按损坏拒绝；原文件同样不得被改写。
	dirA := overlapStore(t, func(s *Store) {
		overlapBaseline(s)
		spec := overlapSpec("cmp-a", upBase, "v2", []string{"d1", "d2"})
		createCampaign(t, s, spec)
		readyDownload(t, s, spec, "d1", upBase)
	})
	dirB := overlapStore(t, func(s *Store) {
		overlapBaseline(s)
		spec := overlapSpec("cmp-b", upBase, "v2", []string{"d1", "d3"})
		createCampaign(t, s, spec)
		readyDownload(t, s, spec, "d1", upBase)
	})
	original := mergeCampaigns(t, dirA, dirB)
	_ = rewriteStoreBytes(t, dirA, func(doc map[string]any) {
		b := campaignDoc(doc, "cmp-b")
		devs := b["devices"].([]any)
		// 删除设备列表中的 d1 条目，保留其结果历史与 d3。
		kept := devs[:0]
		for _, d := range devs {
			if d.(map[string]any)["deviceId"] != "d1" {
				kept = append(kept, d)
			}
		}
		b["devices"] = kept
	})
	s, err := Open(dirA)
	if err == nil {
		s.Close()
		t.Fatalf("dropping the busy device must not yield a usable store")
	}
	if !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("want ErrCorruptStorage, got %v", err)
	}
	// 首次拒绝打开（重叠状态）时文件已必须原样保留。
	if data, rerr := os.ReadFile(filepath.Join(dirA, storeFileName)); rerr != nil {
		t.Fatal(rerr)
	} else if len(data) == 0 {
		t.Fatalf("store file emptied by rejected open")
	}
	_ = original
})

